#!/bin/bash
set -euo pipefail

# This script is invoked from native-ios by build-yueliao.yml.
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
NATIVE="$REPO_ROOT/native-ios"

case "${1:-}" in
  pre)
    cd "$NATIVE"
    test -f project.yml || { echo "error: native-ios/project.yml missing"; exit 1; }
    ICON_SOURCE="$REPO_ROOT/AppIcon-1024.png"
    if [ -f "$ICON_SOURCE" ]; then
      SET="YueLiao/Assets.xcassets/AppIcon.appiconset"
      mkdir -p "$SET"
      cp "$ICON_SOURCE" "$SET/AppIcon-1024.png"
      cat > YueLiao/Assets.xcassets/Contents.json <<'JSON'
{"info":{"author":"xcode","version":1}}
JSON
      cat > "$SET/Contents.json" <<'JSON'
{"images":[{"filename":"AppIcon-1024.png","idiom":"universal","platform":"ios","size":"1024x1024"}],"info":{"author":"xcode","version":1}}
JSON
      echo "App icon ready"
    else
      echo "warning: AppIcon-1024.png not found"
    fi
    # Preserve the project.yml generated by the build workflow.
    echo "patch-ios pre complete"
    ;;
  post)
    cd "$NATIVE"
    PLIST="Payload/YueLiao.app/Info.plist"
    test -f "$PLIST" || { echo "error: $PLIST missing"; exit 1; }
    PB="/usr/libexec/PlistBuddy"
    "$PB" -c "Set :UIUserInterfaceStyle Dark" "$PLIST" 2>/dev/null ||
      "$PB" -c "Add :UIUserInterfaceStyle string Dark" "$PLIST"
    # Do not claim background calling support by adding UIBackgroundModes.
    echo "patch-ios post complete"
    ;;
  *)
    echo "Usage: bash patch-ios.sh pre|post"
    exit 1
    ;;
esac
